# Define your tools
def add(a, b):
    return a + b

def multiply(a, b):
    return a * b

def greet(name):
    return f"Hello, {name}!"

# Tool registry
tools = {
    'add': add,
    'multiply': multiply,
    'greet': greet,
}

# Dispatcher
def dispatch(tool_name, args):
    if tool_name not in tools:
        raise ValueError(f"Unknown tool: {tool_name}")
    return tools[tool_name](*args)

# Test
print(dispatch('add', [3, 5]))
print(dispatch('multiply', [4, 7]))
print(dispatch('greet', ['Muthu']))
